            if type(getexecutorname) == "function" then
                local ex = getexecutorname()
                if ex ~= nil and tostring(ex) ~= "" then named = true; add("P_" .. uid .. "_" .. tostring(ex)) end
            end
        end)
        if not named then add("P_" .. uid .. "_unknown") end
    end
    return ids
end

local function _kwGet(url)
    local ok, resp = pcall(function() return game:HttpGet(url, true) end)
    if not ok or type(resp) ~= "string" then return nil end
    local ok2, decoded = pcall(function() return _KW_HS:JSONDecode(resp) end)
    if not ok2 or type(decoded) ~= "table" or decoded.success ~= true or type(decoded.data) ~= "table" then return nil end
    return decoded.data
end

local function _kwPoll()
    local ids = _kwIdentities()
    if #ids == 0 then return nil end
    local unknown = false
    local i = 1
    while i <= #ids do
        local url = _KW_CHECK_URL .. "?hwid=" .. _KW_HS:UrlEncode(ids[i])
        local j = i + 1
        while j <= #ids and j - i < _KW_BATCH do
            local part = "&alt=" .. _KW_HS:UrlEncode(ids[j])
            if #url + #part > _KW_URL_MAX then break end
            url = url .. part
            j = j + 1
        end
        local d = _kwGet(url)
        if d == nil then
            unknown = true
        elseif d.hasKey == true then
            return true
        elseif d.kw ~= 2 then
            for k = i + 1, j - 1 do
                local dk = _kwGet(_KW_CHECK_URL .. "?hwid=" .. _KW_HS:UrlEncode(ids[k]))
                if dk == nil then unknown = true elseif dk.hasKey == true then return true end
            end
        end
        i = j
    end
    if unknown then return nil end
    return false
end

task.spawn(function()
    while true do
        task.wait(_KW_INTERVAL)
        if _kwPoll() == false then
            task.wait(8)
            if _kwPoll() == false then
                pcall(function() warn(_KW_MSG) end)
                pcall(function() game:GetService("Players").LocalPlayer:Kick(_KW_MSG) end)
                break
            end
        end
    end
end)
